  "Recently used": "Utilisés récemment",
  Showing: "Affiché",
  "Songs added to the service you are building appear here.": "Les chants ajoutés au culte en préparation s’affichent ici.",
  "Songs you show appear here, newest first.": "Les chants affichés apparaissent ici, les plus récents en premier.",
  "Star the songs you sing most and they wait here.": "Mettez une étoile aux chants les plus chantés et ils vous attendent ici.",
  "The assigned display is unavailable.": "L’écran choisi n’est pas disponible.",
  Window: "Fenêtre",

  // Settings: sound, phones, captions, displays, keyboard, stage
  "Listening hears the microphone as it is.": "L’écoute entend le micro tel quel.",
  Light: "Léger",
  "Turns down fans, hum and hiss, and keeps some of the room so quiet words are never lost.": "Atténue ventilateurs, ronflements et souffle, et garde un peu de la salle pour ne jamais perdre les mots prononcés doucement.",
  Strong: "Fort",
  "Removes as much background noise as it can. Best for noisy rooms; very soft speech can drop out.": "Retire autant de bruit de fond que possible. Idéal pour les salles bruyantes ; une voix très douce peut se perdre.",
  "No microphone is connected.": "Aucun micro n’est branché.",
  Move: "Déplacer",
  "Noise filter": "Filtre anti-bruit",
  "Clean the microphone before listening": "Nettoyer le son du micro avant l’écoute",
  "It runs on this computer; no sound leaves it.": "Il fonctionne sur cet ordinateur ; aucun son n’en sort.",
  "Check it in your room": "Vérifier dans votre salle",
  "Play the room as it is on a Sunday (fans, music, the PA) and speak. Compare the two meters.": "Recréez la salle comme un dimanche (ventilateurs, musique, sono) et parlez. Comparez les deux indicateurs.",
  "Stop check": "Arrêter la vérification",
  "Start check": "Lancer la vérification",
  Room: "Salle",
  "What the microphone hears": "Ce que le micro entend",
  "Room level": "Niveau de la salle",
  "After the filter": "Après le filtre",
  "What listening hears": "Ce que l’écoute entend",
  "Level after the filter": "Niveau après le filtre",
  "Background noise is about {cut} dB quieter after the filter.": "Le bruit de fond est environ {cut} dB plus bas après le filtre.",
  "Little to remove here: the room is quiet, or the noise sounds like speech (music, the PA).": "Peu à retirer ici : la salle est calme, ou le bruit ressemble à de la parole (musique, sono).",
  "In this browser": "Dans ce navigateur",
  "Light and Strong turn on the browser's own noise suppression. The desktop app has the stronger filter and the room check.": "Léger et Fort activent la réduction de bruit du navigateur. L’application de bureau a le filtre le plus fort et la vérification de la salle.",
  "Best results": "Meilleurs résultats",
  "A filter removes steady noise, not the PA. If the preacher's voice comes back through the speakers mixed with music, take a feed from the sound desk (an aux send) or put a microphone near the pulpit. That helps detection more than any filter.": "Un filtre retire le bruit continu, pas la sono. Si la voix du prédicateur revient par les haut-parleurs mêlée à la musique, prenez une sortie de la console son (un départ auxiliaire) ou placez un micro près de la chaire. Cela aide la détection plus que n’importe quel filtre.",
  Microphone: "Micro",
  "Test microphone": "Tester le micro",
  "Listens for 20 seconds, long enough to catch a microphone that cuts out shortly after it starts.": "Écoute pendant 20 secondes, assez pour repérer un micro qui se coupe peu après le début.",
  "Stop ({remaining}s)": "Arrêter ({remaining} s)",
  "Start test": "Lancer le test",
  "Input level": "Niveau d’entrée",
  "Speak now…": "Parlez maintenant…",
  "Voice commands": "Commandes vocales",
  "Control the desk hands-free. Spoken verses still go to Preview either way.": "Pilotez le bureau sans les mains. Les versets prononcés passent toujours en aperçu.",
  "Require “Studio” first": "Exiger « Studio » d’abord",
  "Off: just say the words (“next verse”, “give me King James”). A command counts only when it is said on its own, so sermon sentences never act. On: every command starts with “Studio”.": "Désactivé : dites simplement les mots (« next verse », « give me King James »). Une commande ne compte que si elle est dite seule, donc les phrases de la prédication n’agissent jamais. Activé : chaque commande commence par « Studio ».",
  "Require Studio wake word": "Exiger le mot d’éveil Studio",
  "Let voice change Program (go live, cut, clear, black, logo, timer). Off every time Church Studio starts.": "Laisser la voix changer le direct (direct, coupure, effacer, noir, logo, minuteur). Désactivé à chaque démarrage de Church Studio.",
  "Just say": "Dites simplement",
  "Plain words work. These are examples; similar phrasings work too.": "Des mots simples suffisent. Ce sont des exemples ; des formulations proches marchent aussi.",
  "Custom commands": "Commandes personnalisées",
  "Remove {phrase}": "Retirer {phrase}",
