  "Bitfocus Companion (Stream Deck), MIDI bridges and scripts press buttons by opening a link. Each controller gets its own key.": "Bitfocus Companion (Stream Deck), les passerelles MIDI et les scripts appuient sur les boutons en ouvrant un lien. Chaque contrôleur reçoit sa propre clé.",
