  "OBS, vMix or an NDI monitor can take what the audience sees, over the network. This works in the Church Studio app for Mac.": "OBS, vMix ou un moniteur NDI peut recevoir ce que voit l’assemblée, par le réseau. Cela marche dans l’application Church Studio pour Mac.",
