  "Sending the scripture and lyrics on Program as “{name}”, on a transparent background.": "Envoi des passages et des paroles du direct sous le nom « {name} », sur fond transparent.",
  "A second source with only the scripture or lyrics on Program, as a lower third on a transparent background. Lay it over a camera in OBS or vMix. It needs no screen recording permission.": "Une seconde source avec seulement les passages ou paroles du direct, en bas d’écran sur fond transparent. Posez-la sur une caméra dans OBS ou vMix. Aucune autorisation d’enregistrement d’écran n’est nécessaire.",
