  "Untitled sermon": "Prédication sans titre",
  "No speaker": "Pas d’orateur",
  "Notes for the section on Preview show here. They never reach Preview or Program.": "Les notes de la partie en aperçu s’affichent ici. Elles n’arrivent jamais à l’aperçu ni au direct.",
  "New part": "Nouvelle partie",
  Lobby: "Hall",
  "Make one at api.planningcenteronline.com › Personal Access Tokens, then paste the application id and secret. They stay on this computer.": "Créez-en un sur api.planningcenteronline.com › Personal Access Tokens, puis collez l’identifiant d’application et le secret. Ils restent sur cet ordinateur.",
  "Pick a folder your cloud drive keeps (Google Drive, OneDrive, Dropbox, iCloud). Church Studio saves there every 30 minutes and keeps the newest 20.": "Choisissez un dossier synchronisé par votre stockage en ligne (Google Drive, OneDrive, Dropbox, iCloud). Church Studio y enregistre toutes les 30 minutes et garde les 20 plus récentes.",
  "Last backup {date}": "Dernière sauvegarde {date}",
  "On another computer, choose the same folder and restore: songs, services, sermons, slide decks, looks and layouts come across. Display settings stay per computer.": "Sur un autre ordinateur, choisissez le même dossier et restaurez : chants, cultes, prédications, présentations, compositions et dispositions sont repris. Les réglages d’écran restent propres à chaque ordinateur.",
  "Backed up.": "Sauvegardé.",
  "NIV, NKJV, ESV and others, where the publisher allows it. Get a free key at scripture.api.bible; text is fetched when shown and needs the internet.": "NIV, NKJV, ESV et d’autres, là où l’éditeur le permet. Obtenez une clé gratuite sur scripture.api.bible ; le texte est chargé à l’affichage et demande Internet.",
  "{count} more in the CSV.": "{count} de plus dans le CSV.",
  "Connect a camera, then refresh.": "Branchez une caméra, puis actualisez.",
  "If macOS refused the mic, turn Church Studio on under Microphone and Speech Recognition.": "Si macOS a refusé le micro, activez Church Studio sous Micro et Reconnaissance vocale.",
  "Until {date}": "Jusqu’au {date}",
  "{kind} background.": "Fond : {kind}.",
  "Larger for a stage screen far from the pulpit.": "Plus grand pour un écran de scène loin de la chaire.",
  "Stage text size": "Taille du texte de scène",
  "Set up the AI in Settings › AI assistant first.": "Configurez d’abord l’IA dans Réglages › Assistant IA.",
  "Paste your key first.": "Collez d’abord votre clé.",
  "No models yet. Download one in Ollama or LM Studio first.": "Aucun modèle pour l’instant. Téléchargez-en un dans Ollama ou LM Studio d’abord.",
  "The AI service listed no models for this key.": "Le service d’IA n’a listé aucun modèle pour cette clé.",
  "Nothing answered on this computer. Open Ollama or LM Studio, and check the address.": "Rien n’a répondu sur cet ordinateur. Ouvrez Ollama ou LM Studio et vérifiez l’adresse.",
  "Slides are written by your own AI: Claude, ChatGPT, Gemini, or an AI on this computer. Set it up once.": "Les diapositives sont écrites par votre propre IA : Claude, ChatGPT, Gemini ou une IA sur cet ordinateur. Configurez-la une fois.",
  "Set up the AI first": "Configurez d’abord l’IA",
  "Translation uses your own AI.": "La traduction utilise votre propre IA.",
  "Set it up in AI assistant": "Configurez-la dans Assistant IA",
  "Claude, ChatGPT, Gemini or an AI on this computer, for sermons, slides, songs and captions.": "Claude, ChatGPT, Gemini ou une IA sur cet ordinateur, pour les prédications, les diapositives, les chants et les sous-titres.",
  "Which AI": "Quelle IA",
  "Claude, ChatGPT and Gemini work over the internet with a key from their website. An AI on this computer works without a key or the internet.": "Claude, ChatGPT et Gemini fonctionnent par internet avec une clé obtenue sur leur site. Une IA sur cet ordinateur fonctionne sans clé ni internet.",
  "Claude (by Anthropic)": "Claude (d’Anthropic)",
  "ChatGPT (by OpenAI)": "ChatGPT (d’OpenAI)",
  "Gemini (by Google)": "Gemini (de Google)",
  "An AI on this computer": "Une IA sur cet ordinateur",
  "Set it up once": "À configurer une fois",
  "Install Ollama (ollama.com) or LM Studio (lmstudio.ai), download a model in it, and keep the app open while you use Church Studio. Nothing leaves this computer.": "Installez Ollama (ollama.com) ou LM Studio (lmstudio.ai), téléchargez-y un modèle et gardez l’application ouverte pendant que vous utilisez Church Studio. Rien ne quitte cet ordinateur.",
  "Which app": "Quelle application",
  "Where the AI app listens on this computer. Pick yours, or type another address.": "L’adresse où l’application d’IA écoute sur cet ordinateur. Choisissez la vôtre ou tapez une autre adresse.",
  "Get one at console.anthropic.com › API Keys.": "Obtenez-en une sur console.anthropic.com › API Keys.",
  "Get one at platform.openai.com › API keys.": "Obtenez-en une sur platform.openai.com › API keys.",
  "Get one at aistudio.google.com › Get API key. Google has a free tier.": "Obtenez-en une sur aistudio.google.com › Get API key. Google propose une offre gratuite.",
  "It stays on this computer. The company may charge you for what you use.": "Elle reste sur cet ordinateur. L’entreprise peut vous facturer ce que vous utilisez.",
  "The version of the AI to use. claude-sonnet-5-5 is a good balance; claude-haiku-5-5 is quicker and cheaper.": "La version de l’IA à utiliser. claude-sonnet-5-5 est un bon équilibre ; claude-haiku-5-5 est plus rapide et moins cher.",
  "The version of the AI to use. Press Find models to see the ones you can use.": "La version de l’IA à utiliser. Appuyez sur Trouver les modèles pour voir ceux que vous pouvez utiliser.",
  "Choose a model first. Find models lists them.": "Choisissez d’abord un modèle. Trouver les modèles les affiche.",
  "Waiting for the AI to answer. This can take up to a minute.": "En attente de la réponse de l’IA. Cela peut prendre jusqu’à une minute.",
  "Choose a model": "Choisir un modèle",
  "Model name": "Nom du modèle",
  "Find models": "Trouver les modèles",
  "Sends a short test to the AI.": "Envoie un court test à l’IA.",
  "Type a title, a line you remember, or what the song is about.": "Tapez un titre, une phrase dont vous vous souvenez ou le sujet du chant.",
  "The AI found no song for that. Try other words.": "L’IA n’a trouvé aucun chant. Essayez d’autres mots.",
