  "Look up a song with AI": "Rechercher un chant avec l’IA",
  "Songs are looked up by your own AI: Claude, ChatGPT, Gemini, or an AI on this computer. Set it up once.": "Les chants sont recherchés par votre propre IA : Claude, ChatGPT, Gemini ou une IA sur cet ordinateur. Configurez-la une fois.",
