  "Import the file": "Importer le fichier",
  "Old hymns in the public domain: the AI writes the words for you to check. Other songs: download them from SongSelect with your CCLI license, then import the file.": "Anciens cantiques du domaine public : l’IA écrit les paroles, à vérifier. Autres chants : téléchargez-les sur SongSelect avec votre licence CCLI, puis importez le fichier.",
  "For songs you don't have yet. The AI names the song, its writers and its CCLI number, and can be wrong: check before it goes on screen.": "Pour les chants que vous n’avez pas encore. L’IA donne le titre, les auteurs et le numéro CCLI, et peut se tromper : vérifiez avant l’affichage.",
  "The AI wrote these words. Check every line before they go on screen, then Save.": "L’IA a écrit ces paroles. Vérifiez chaque ligne avant l’affichage, puis enregistrez.",
  "Look up a song with AI…": "Rechercher un chant avec l’IA…",
  "Songs you don't have yet: words for old hymns, SongSelect for the rest.": "Chants que vous n’avez pas encore : les paroles des anciens cantiques, SongSelect pour les autres.",
