  "Queue cleared": "File vidée",
  "{feature} is part of {plan}. Choose the plan that fits your church.": "{feature} fait partie de {plan}. Choisissez l’abonnement qui convient à votre église.",
  "The Production Desk trial could not start: {reason} You can start on the Presenter Desk and try again from Settings › Plan & account.": "L’essai du pupitre Production n’a pas pu démarrer : {reason} Vous pouvez commencer sur le pupitre Présentation et réessayer depuis Réglages › Abonnement et compte.",
  "Clear everything back to the theme": "Tout effacer et revenir au thème",
  "Click again to clear": "Cliquez à nouveau pour vider",
  "Nothing queued. Add puts the verse on Preview into the service, to show later in order.": "Rien dans la file. Ajouter place le verset de l’aperçu dans le culte, pour l’afficher plus tard dans l’ordre.",
  "This song has unsaved changes. Click again to discard them, or press Save.": "Ce chant a des modifications non enregistrées. Cliquez à nouveau pour les abandonner, ou appuyez sur Enregistrer.",
  "Discard changes": "Abandonner les modifications",
  Account: "Compte",
  // 0.2.4
  "Bring your songs from ProPresenter and EasyWorship": "Apportez vos chants depuis ProPresenter et EasyWorship",
  "Import ProPresenter files or a whole EasyWorship library from Songs › Import, with parts, order and CCLI details.": "Importez des fichiers ProPresenter ou toute une bibliothèque EasyWorship depuis Chants › Importer, avec les parties, l’ordre et les informations CCLI.",
  "Your own Bible, offline": "Votre propre Bible, hors ligne",
  "Import a Bible file in your church's language (Zefania, OSIS or OpenSong) in Settings › Bible.": "Importez un fichier Bible dans la langue de votre église (Zefania, OSIS ou OpenSong) dans Réglages › Bible.",
  "Chords for the band": "Des accords pour les musiciens",
  "Songs from ChordPro files show chords on the stage screen, and the song desk can change their key.": "Les chants issus de fichiers ChordPro affichent les accords sur l’écran de scène, et le pupitre des chants peut changer leur tonalité.",
  "Smoother setup": "Une installation plus simple",
  "Setup ends with a verse ready to show, and the desk says when a trial ends or the plan needs to check in.": "L’installation se termine avec un verset prêt à afficher, et le pupitre indique quand un essai se termine ou quand l’abonnement doit se vérifier.",
  // 0.2.3
  "Undo on Program": "Annuler sur Programme",
  "Cleared or blacked the screen by mistake? Press Undo, or Command-Z (Ctrl+Z on Windows), and it comes back.": "Écran effacé ou mis au noir par erreur ? Appuyez sur Annuler, ou Commande-Z (Ctrl+Z sous Windows), et il revient.",
  "Keys for song parts": "Des touches pour les parties des chants",
  "Press 1 to 9 for a part, or Shift with V, C or B for the next verse, chorus or bridge.": "Appuyez sur 1 à 9 pour une partie, ou Maj avec V, C ou B pour le couplet, le refrain ou le pont suivant.",
  "The desk tells you what happened": "Le pupitre vous dit ce qui s’est passé",
  "A short line at the bottom explains when something could not be done, in amber when it matters.": "Une courte ligne en bas explique quand quelque chose n’a pas pu être fait, en ambre quand c’est important.",
  "Safer by default": "Plus sûr par défaut",
  "Clearing the queue takes two clicks and can be undone, unsaved song edits ask first, and Preview buttons stay on Preview.": "Vider la file demande deux clics et peut être annulé, les modifications de chant non enregistrées demandent d’abord, et les boutons d’aperçu restent sur l’aperçu.",
  // 0.2.2
  "Walk-in with a countdown": "L’accueil avec un compte à rebours",
  "Start walk-in from Audio: the countdown goes on the screen, the music plays, and it fades by itself when the service starts.": "Lancez l’accueil depuis Audio : le compte à rebours passe à l’écran, la musique joue et s’estompe d’elle-même au début du culte.",
  "Music that sounds right": "Une musique qui sonne juste",
  "Tracks play at an even volume and fade into each other, and playlists can shuffle.": "Les pistes jouent à un volume égal et s’enchaînent en fondu, et les listes peuvent être jouées en aléatoire.",
  "A sound pad": "Un pad sonore",
  "Play an offering bell or an intro sting with one click, over everything else.": "Jouez une cloche d’offrande ou un jingle d’introduction d’un clic, par-dessus le reste.",
  "Backing tracks for songs": "Des pistes d’accompagnement pour les chants",
  "Give a song a backing track in the song editor, and it plays when the song goes live.": "Donnez une piste d’accompagnement à un chant dans l’éditeur : elle joue quand le chant passe en direct.",
  "Music from your phone": "La musique depuis votre téléphone",
  "The phone remote can play, skip and fade the music.": "La télécommande sur téléphone peut lancer, passer et estomper la musique.",
  // 0.2.1
  "Songs line by line": "Les chants ligne par ligne",
  "Choose how many lines show at once with Lines on the song desk. The arrows step through them, and listening follows the line being sung.": "Choisissez combien de lignes s’affichent à la fois avec Lignes sur le pupitre des chants. Les flèches les font défiler et l’écoute suit la ligne chantée.",
  "Faster verse and song detection": "Détection plus rapide des versets et des chants",
  "What is read or sung reaches Preview much sooner, even with a large song library.": "Ce qui est lu ou chanté arrive sur Aperçu bien plus tôt, même avec une grande bibliothèque de chants.",
  "Your playlists stay as you left them": "Vos listes de lecture restent telles que vous les avez laissées",
  "Church Studio now opens only once, so a second copy can no longer save over your music.": "Church Studio ne s’ouvre plus qu’une fois : une deuxième copie ne peut plus écraser votre musique.",
  "Updates come to you": "Les mises à jour viennent à vous",
  "When a new version is ready, a note on the desk offers it, to install after the service.": "Quand une nouvelle version est prête, une note sur le pupitre la propose, à installer après le culte.",
  // Songs line by line
  "lines {n} of {total}": "lignes {n} sur {total}",
