  "Optional. Sign in with an email link in your browser, and another computer only needs you to sign in. No key to copy.": "Facultatif. Connectez-vous avec un lien par e-mail dans votre navigateur : sur un autre ordinateur, il suffit de vous connecter. Aucune clé à copier.",
  "Plans and a free trial": "Abonnements et essai gratuit",
