  "About a minute. The preview beside you changes as you answer, so you see your Sunday before it starts.": "Environ une minute. L’aperçu à côté change au fil de vos réponses : vous voyez votre dimanche avant qu’il commence.",
  "Scripture, songs and sermons, ready offline": "Écritures, chants et prédications, prêts hors ligne",
  "Say “next verse” and the desk follows": "Dites « verset suivant » et le bureau suit",
