  "Tell us about your church": "Parlez-nous de votre église",
  "The name becomes your logo slide. Tick what you show and the preview shows it.": "Le nom devient votre diapositive de logo. Cochez ce que vous montrez et l’aperçu l’affiche.",
  "What you put on screen": "Ce que vous mettez à l’écran",
  "On Sunday we show": "Le dimanche, nous montrons",
  "How it looks on the wall": "Le rendu au mur",
  "Pick the look for verses, songs and your logo slide. Preview and Program change as you pick; the theme library has many more.": "Choisissez le style des versets, des chants et de votre diapositive de logo. L’Aperçu et le Direct changent au fil de vos choix ; la bibliothèque de thèmes en propose bien d’autres.",
  "Colors for your desk": "Couleurs de votre bureau",
  "This is the desk you work at. The congregation never sees it, so pick what is easy on your eyes in your room.": "C’est le bureau sur lequel vous travaillez. L’assemblée ne le voit jamais : choisissez ce qui repose vos yeux dans votre salle.",
  "Choose your Bible": "Choisissez votre Bible",
  "King James and the World English Bible are installed. Add others now or any time from Settings.": "La King James et la World English Bible sont installées. Ajoutez-en d’autres maintenant ou à tout moment dans Réglages.",
  "{sizeMb} MB": "{sizeMb} Mo",
  "Put it on the big screen": "Affichez-le sur le grand écran",
  "Plug in the projector or TV first. The audience window opens there, full screen, and shows only what you send live.": "Branchez d’abord le projecteur ou la télé. La fenêtre de l’assemblée s’y ouvre en plein écran et n’affiche que ce que vous envoyez au direct.",
  "Open the audience window": "Ouvrir la fenêtre de l’assemblée",
  "It is open. Move it to the projector if it opened here.": "Elle est ouverte. Déplacez-la vers le projecteur si elle s’est ouverte ici.",
  "It opens on the second screen when there is one.": "Elle s’ouvre sur le second écran s’il y en a un.",
  "Check it from the back row": "Vérifiez depuis le dernier rang",
  "A test pattern flashes on the audience screen. Nothing live changes.": "Une mire s’affiche brièvement sur l’écran de l’assemblée. Rien ne change au direct.",
  "Fit any screen": "S’adapter à tout écran",
