  "Test mode: a test checkout opens and nothing is charged.": "Mode test : un paiement test s’ouvre et rien n’est prélevé.",
  "The checkout took too long. If you paid, your key is in your email.": "Le paiement a pris trop de temps. Si vous avez payé, votre clé est dans votre e-mail.",
