  "This computer's clock is set earlier than it was. Set the date and time correctly; paid features are paused until then.": "L’horloge de cet ordinateur a été reculée. Réglez la date et l’heure ; les fonctions payantes sont en pause d’ici là.",
  "This key is in use on all the computers it covers. Release one below, then check again.": "Cette clé est utilisée sur tous les ordinateurs qu’elle couvre. Libérez-en un ci-dessous, puis vérifiez à nouveau.",
