  "Report a security problem": "Signaler un problème de sécurité",
  "Learned: “{heard}” means {means}": "Appris : « {heard} » veut dire {means}",
  "Next time it is put right by itself. If that was wrong, remove it.": "La prochaine fois, il sera corrigé tout seul. Si c’est faux, supprimez-le.",
  "Misheard words": "Mots mal compris",
  "Accents and names the recognizer gets wrong are put right before verses are found: “efficient 4” becomes Ephesians 4. A book name changes only next to a chapter number, so ordinary speech keeps its words. When you put up a passage the recognizer missed, Church Studio learns the word by itself.": "Les accents et les noms que la reconnaissance comprend mal sont corrigés avant la recherche des versets : « efficient 4 » devient Éphésiens 4. Un nom de livre n’est changé qu’à côté d’un numéro de chapitre, donc le langage courant garde ses mots. Quand vous affichez un passage que la reconnaissance a manqué, Church Studio apprend le mot tout seul.",
  "Practice": "Entraînement",
  "Read references aloud, as the pastor would, and see what the recognizer writes. Teach it any word it gets wrong.": "Lisez des références à voix haute, comme le pasteur, et voyez ce que la reconnaissance écrit. Apprenez-lui les mots qu’elle comprend mal.",
  "Say": "Dites",
  "Listening…": "Écoute…",
  "Put right": "Corrigé",
  "Found {reference}": "{reference} trouvé",
  "No verse found yet.": "Aucun verset trouvé pour l’instant.",
  "Was “{guess}” {book}?": "« {guess} » voulait-il dire {book} ?",
  "Teach it": "Lui apprendre",
  "Next reference": "Référence suivante",
  "Start practice": "Commencer l’entraînement",
