  "Timer reset. Start it when ready.": "Minuteur remis à zéro. Lancez-le quand vous êtes prêt.",
  "Connected. The test made {n} point.": "Connecté. Le test a produit {n} point.",
  "Connected. The test made {n} points.": "Connecté. Le test a produit {n} points.",
