  "{name} could not be opened.": "{name} n’a pas pu être ouvert.",
  // Accounts: signing in, the people on a license, and signed-in computers
  "Connect to the internet to change who uses this license.": "Connectez-vous à Internet pour changer qui utilise cette licence.",
  "Connect to the internet to see where you are signed in.": "Connectez-vous à Internet pour voir où vous êtes connecté.",
  "Connect to the internet to sign a computer out.": "Connectez-vous à Internet pour déconnecter un ordinateur.",
  "Everything is unlocked, on any computer you sign in on.": "Tout est débloqué, sur chaque ordinateur où vous vous connectez.",
  "Sign in in your browser to add this key. It is added as soon as you are signed in.": "Connectez-vous dans votre navigateur pour ajouter cette clé. Elle est ajoutée dès que vous êtes connecté.",
  "Sign in in your browser to start your free trial. It stays with you on any computer.": "Connectez-vous dans votre navigateur pour commencer votre essai gratuit. Il vous suit sur chaque ordinateur.",
  "Google, Microsoft, Apple or an email link. Your trial and any plan follow you to every computer. You can also sign in later.": "Google, Microsoft, Apple ou un lien par e-mail. Votre essai et votre formule vous suivent sur chaque ordinateur. Vous pouvez aussi vous connecter plus tard.",
  "Sign in there, then type this code.": "Connectez-vous là-bas, puis tapez ce code.",
  "Sign in to start your free trial": "Connectez-vous pour commencer votre essai gratuit",
  "Type {code} on the sign-in page": "Tapez {code} sur la page de connexion",
  "A computer nobody opens for six months signs itself out.": "Un ordinateur que personne n’ouvre pendant six mois se déconnecte tout seul.",
  "Add person": "Ajouter",
  "Add someone by email and they get an invitation from you. Once they sign in with that address, their computers use this license, up to its seats.": "Ajoutez quelqu’un par e-mail et il reçoit une invitation de votre part. Dès qu’il se connecte avec cette adresse, ses ordinateurs utilisent cette licence, dans la limite de ses postes.",
  "On this network": "Sur ce réseau",
  "Pictures and videos come from the computers on this network first: faster, and they do not need the cloud space.": "Les images et les vidéos viennent d’abord des ordinateurs de ce réseau : c’est plus rapide, et cela n’utilise pas l’espace cloud.",
  "Joined {date}": "A rejoint le {date}",
  "Invited {date} · not joined yet": "Invité le {date} · pas encore inscrit",
  "Not joined yet": "Pas encore inscrit",
  "Resend invite": "Renvoyer l’invitation",
  "Send invite": "Envoyer l’invitation",
  "Invitation sent to {email}": "Invitation envoyée à {email}",
  "They download Church Studio and sign in with that address. No license key needed.": "Il suffit de télécharger Church Studio et de se connecter avec cette adresse. Aucune clé de licence.",
  "{name}'s plan is in use on all the computers it covers. Ask {name} to free one, then sign in again.": "L’abonnement de {name} est utilisé sur tous les ordinateurs qu’il couvre. Demandez à {name} d’en libérer un, puis reconnectez-vous.",
  "Email to add": "E-mail à ajouter",
  "Needed for the free trial and to add a license key. Your plan then follows you, so another computer only needs you to sign in. Google, Microsoft, Apple or an email link, in your browser.": "Nécessaire pour l’essai gratuit et pour ajouter une clé de licence. Votre formule vous suit ensuite : sur un autre ordinateur, il suffit de vous connecter. Google, Microsoft, Apple ou un lien par e-mail, dans votre navigateur.",
  "Open the page on any phone or computer, sign in, then type:": "Ouvrez la page sur n’importe quel téléphone ou ordinateur, connectez-vous, puis tapez :",
  "People on your {plan} license": "Personnes sur votre licence {plan}",
  "Show computers": "Afficher les ordinateurs",
  "Sign in on another device": "Se connecter sur un autre appareil",
  "Sign in there and choose Continue. Church Studio carries on by itself.": "Connectez-vous là-bas et choisissez Continuer. Church Studio reprend tout seul.",
  "Sign out everywhere else": "Se déconnecter partout ailleurs",
  "Sign-in code {code}": "Code de connexion {code}",
  "Type this code on the sign-in page": "Tapez ce code sur la page de connexion",
  "Use a code instead": "Utiliser un code",
  "Where you are signed in": "Où vous êtes connecté",
  // What's new in 0.3.0
  "Sign in once, in your browser": "Connexion unique, dans votre navigateur",
  "Sign in comes back to Church Studio by itself, with no number to tap. From a phone or another computer, type the short code instead.": "La connexion revient toute seule dans Church Studio, sans numéro à toucher. Depuis un téléphone ou un autre ordinateur, tapez plutôt le code court.",
  "Your plan goes with you": "Votre formule vous suit",
  "The free trial and license keys now belong to your account. Add your team by email in Settings › Account, and see every computer you are signed in on.": "L’essai gratuit et les clés de licence appartiennent maintenant à votre compte. Ajoutez votre équipe par e-mail dans Réglages › Compte, et voyez chaque ordinateur où vous êtes connecté.",
  "Steadier on Sunday": "Plus stable le dimanche",
  "Installing a Bible, importing a video or starting to listen no longer freezes the desk or the projector, and quick clicks through verses always land on the right one.": "Installer une Bible, importer une vidéo ou commencer l’écoute ne fige plus le pupitre ni le projecteur, et des clics rapides sur les versets tombent toujours sur le bon.",
  "Every screen shape": "Toutes les formes d’écran",
  "Looks with gaps or frames, theme previews and slide pages follow your screen's real shape, 4:3 and portrait included.": "Les vues avec espaces ou cadres, les aperçus de thèmes et les pages de diapositives suivent la vraie forme de votre écran, 4:3 et portrait compris.",
  "Clearer in French and Spanish": "Plus clair en français et en espagnol",
  "Desk messages are translated, and problems stand out as warnings in every language.": "Les messages du pupitre sont traduits, et les problèmes ressortent comme des avertissements dans toutes les langues.",
