  "Name of the quiz or poll": "Nom du quiz ou du sondage",
  "Each question has a right answer. Points, a leaderboard and a podium.": "Chaque question a une bonne réponse. Des points, un classement et un podium.",
  "No right answer. The room sees how everyone voted.": "Pas de bonne réponse. La salle voit comment chacun a voté.",
  "Description and sermon series": "Description et série de prédications",
  "Paste or type your questions": "Collez ou tapez vos questions",
  "Write them one by one instead": "Les écrire une par une",
  "Who built the ark?\n* Noah\nMoses\nAbraham\n\nHow many disciples did Jesus choose?\nSeven\n* Twelve\nSeventy": "Qui a construit l’arche ?\n* Noé\nMoïse\nAbraham\n\nCombien de disciples Jésus a-t-il choisis ?\nSept\n* Douze\nSoixante-dix",
  "The first line is the question, each line after it an answer.": "La première ligne est la question, chaque ligne suivante une réponse.",
  "Leave an empty line between questions.": "Laissez une ligne vide entre les questions.",
  "Put * before the right answer, or add a line like Answer: B.": "Mettez * devant la bonne réponse, ou ajoutez une ligne comme Answer: B.",
  "Numbers and letters in front, like 1. or a), are fine.": "Les numéros et lettres devant, comme 1. ou a), sont acceptés.",
  "Add questions": "Ajouter les questions",
